from fractions import Fraction as Q
from itertools import product

def check_fixture(doc):
    labels=[]
    def check(label,condition):
        assert condition,label
        labels.append(label)
    def canonical(G):
        return all(set(c)==set(range(1,max(c)+1)) for c in zip(*G))
    def counts(theta,G):
        n,D=len(theta),len(theta[0]); N=[0]*D; F=[0]*D; C=[0]*D; rev=[0]*D; eq=[0]*D
        for d in range(D):
            for i in range(n):
                for j in range(i+1,n):
                    if G[i][d]==G[j][d]: continue
                    a,b=(i,j) if G[i][d]<G[j][d] else (j,i)
                    N[d]+=1
                    c=Q(theta[a][d]); z=Q(theta[b][d])
                    F[d]+=int(c<=z); C[d]+=int(c>z); rev[d]+=int(c<z); eq[d]+=int(c==z)
        return N,F,C,rev,eq
    def evaluate(c,G,tau=None):
        tau=[Q(x) for x in (tau or c['tau'])]; w=list(map(Q,c['weights']))
        n,D=c['n'],c['D']; M=Q(n*(n-1),2)
        R=Q(0); K=Q(0); T=Q(0); J=Q(0); EF=[Q(0)]*D
        N=None
        for st in c['states']:
            mass=Q(st['mass']); N,F,C,rev,eq=counts(st['theta'],G)
            R+=mass*sum(w[d]*(F[d]+tau[d]*(M-N[d]))/M for d in range(D))
            EF=[v+mass*f for v,f in zip(EF,F)]
            prot=c.get('protection')
            if prot and any(F[d]>Q(prot['t'][d])*N[d] for d in prot['domains']): J+=mass
            if D==1 and 'lambda' in c:
                K+=mass*(rev[0]-Q(c['lambda'])*C[0])/M
                T+=mass*eq[0]
        feasible=(not c.get('protection')) or J<=Q(c['protection']['alpha'])
        return {'R':R,'K':K,'T':T,'J':J,'N':N,'EF':EF,'feasible':feasible,'I':sum(N)}
    summary={}
    for c in doc['cases']:
        cid=c['id']; n,D=c['n'],c['D']; M=Q(n*(n-1),2)
        check(cid+' proper masses',sum(Q(s['mass']) for s in c['states'])==1 and all(Q(s['mass'])>=0 for s in c['states']))
        check(cid+' loss weights',sum(map(Q,c['weights']))==1 and all(Q(w)>=0 for w in c['weights']))
        check(cid+' positive admissible costs',all(0<Q(t)<=Q(1,2) for t in c['tau']))
        check(cid+' state dimensions',all(len(s['theta'])==n and all(len(r)==D for r in s['theta']) for s in c['states']))
        all0=[[1]*D for _ in range(n)]; z=evaluate(c,all0)
        check(cid+' all-withheld feasible',z['feasible'] and z['J']==0 and all(v==0 for v in z['N']) and all(v==0 for v in z['EF']))
        check(cid+' all-withheld risk',z['R']==sum(Q(w)*Q(t) for w,t in zip(c['weights'],c['tau'])))
        if cid=='RED-COMMON':
            G=c['action']; check(cid+' canonical diagonal',canonical(G) and len(set(zip(*G)))==1)
            N,F,C,rev,eq=counts(c['states'][0]['theta'],G)
            check(cid+' count once',N==c['expected_N'] and F==c['expected_F'])
            for v in c['cost_variants']:
                out=evaluate(c,G,v['tau']); tb=sum(Q(w)*Q(t) for w,t in zip(c['weights'],v['tau']))
                p1=(sum(Q(w)*f for w,f in zip(c['weights'],F))+tb*(M-N[0]))/M
                check(cid+' '+v['id']+' exact risk',out['R']==Q(v['expected_R']))
                check(cid+' '+v['id']+' matched P1',p1==out['R'] and tb==Q(v['effective_tau']))
            check(cid+' unmatched tau changes risk',Q(c['cost_variants'][0]['expected_R'])!=Q(c['cost_variants'][1]['expected_R']))
            summary[cid]={'counted_disclosures':N,'counted_errors':F}
            continue
        if cid=='RED-ZERO-WEIGHT':
            columns=[(1,2),(1,1),(2,1)]
            acts={a+'|'+b:[list(row) for row in zip(ca,cb)] for (a,ca),(b,cb) in product(zip(['forward','withheld','reverse'],columns),repeat=2)}
        else:
            acts={a['name']:a['G'] for a in c['actions']}
        results={}
        for name,G in acts.items():
            check(cid+' '+name+' canonical',canonical(G))
            o=evaluate(c,G);results[name]=o
            check(cid+' '+name+' bounded risk',0<=o['R']<=1)
            if 'expected_weak_risks' in c:check(cid+' '+name+' weak risk',o['R']==Q(c['expected_weak_risks'][name]))
            if 'expected_strict_risks' in c:
                check(cid+' '+name+' strict risk',o['K']==Q(c['expected_strict_risks'][name]))
                tau=Q(c['tau'][0]); bridge=tau+(1-tau)*o['K']; correction=(1-tau)*o['T']/M
                check(cid+' '+name+' exact correction',o['R']==bridge+correction)
                if cid=='RED-SCALAR':check(cid+' '+name+' no-tie affine',o['R']==bridge)
        feasible={name:o for name,o in results.items() if o['feasible']}
        check(cid+' nonempty feasible family',bool(feasible))
        minimum=min(o['R'] for o in feasible.values()); maximum=max(o['I'] for o in feasible.values())
        amin=sorted(name for name,o in feasible.items() if o['R']==minimum)
        bmax=sorted(name for name,o in feasible.items() if o['I']==maximum)
        check(cid+' feasible minimizers',amin==sorted(c['expected_feasible_weak_minimizers']))
        if 'expected_feasible_actions' in c:check(cid+' feasible actions',sorted(feasible)==sorted(c['expected_feasible_actions']))
        if 'expected_unconstrained_weak_minimizers' in c:
            mn=min(o['R'] for o in results.values())
            check(cid+' unconstrained weak minimizers',sorted(k for k,v in results.items() if v['R']==mn)==sorted(c['expected_unconstrained_weak_minimizers']))
        if 'expected_strict_minimizers' in c:
            mk=min(o['K'] for o in results.values())
            check(cid+' strict minimizers',sorted(k for k,v in results.items() if v['K']==mk)==sorted(c['expected_strict_minimizers']))
        if cid=='RED-EQUALITY':check(cid+' unconditional bridge fails',results['forward']['R']!=Q(c['tau'][0])+(1-Q(c['tau'][0]))*results['forward']['K'])
        if cid=='RED-ZERO-WEIGHT':
            check(cid+' zero-weight wrong direction infeasible',not results['forward|reverse']['feasible'])
            check(cid+' risk minimizer not unique',len(amin)==2)
            check(cid+' auxiliary solution set differs',bmax==['forward|forward'] and amin!=bmax)
        summary[cid]={'feasible_actions':sorted(feasible),'risk_minimizers':amin,'disclosure_maximizers':bmax,'minimum_risk':str(minimum),'maximum_disclosures':maximum}
    return {'status':'PASS','assertions':len(labels),'arithmetic':'exact fractions.Fraction; no simulated draws','case_count':len(doc['cases']),'check_labels':labels,'case_summaries':summary}
